1813 /// Matches shuffle.
1814 template <typename T0, typename T1, typename T2> struct Shuffle_match {
1815   T0 Op1;
1816   T1 Op2;
1817   T2 Mask;
1818 
1819   Shuffle_match(const T0 &Op1, const T1 &Op2, const T2 &Mask)
1820       : Op1(Op1), Op2(Op2), Mask(Mask) {}
